'use client';

import { WordRotate } from '@/components/core/word-rotate';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ArrowRightIcon, ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';

import { HERO } from './data';
import { InstallChip } from './install-chip';
import { LiveRun } from './live-run';

/** How long each last word of the title stays before the next one turns in, in seconds. */
const WORD_INTERVAL_S = 2.8;

function AnnouncementLink() {
  return (
    <a
      href={HERO.announcement.href}
      className='group bg-foreground/[0.04] hover:bg-foreground/[0.07] focus-visible:ring-ring/25 inline-flex max-w-full items-center gap-2 rounded-full py-1 ps-1 pe-3 text-xs font-medium transition-[background-color,scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-[3px] active:scale-[0.97]'
    >
      <Badge className='rounded-full'>{HERO.announcement.label}</Badge>
      <span className='truncate'>{HERO.announcement.text}</span>
      <ChevronRightIcon className='text-muted-foreground size-3.5 shrink-0 transition-transform duration-150 ease-(--ease-out-strong) group-hover:translate-x-0.5' />
    </a>
  );
}

export default function Heroes06() {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <section className='@container'>
      <div className='mx-auto grid max-w-6xl items-center gap-12 px-4 py-16 @2xl:px-6 @2xl:py-24 @4xl:grid-cols-[minmax(0,1fr)_24rem] @4xl:gap-16'>
        <div className='flex min-w-0 flex-col items-start gap-6'>
          <AnnouncementLink />
          <h1 className='text-4xl font-semibold text-balance @2xl:text-5xl'>
            {HERO.titleStart}{' '}
            <span className='text-primary-ink block'>
              <WordRotate
                words={HERO.titleWords}
                interval={WORD_INTERVAL_S}
                paused={shouldReduceMotion}
                accessibleText={HERO.titleSpoken}
              />
            </span>
          </h1>
          <p className='text-muted-foreground max-w-xl text-base text-pretty'>
            {HERO.description}
          </p>
          <div className='flex flex-wrap gap-2'>
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {HERO.primaryAction}
              <ArrowRightIcon />
            </Button>
            <Button
              size='lg'
              variant='outline'
              nativeButton={false}
              render={<a href='#' />}
            >
              {HERO.secondaryAction}
            </Button>
          </div>
          <InstallChip command={HERO.command} />
        </div>
        <LiveRun />
      </div>
    </section>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  type PlanStep,
  type RunSnapshot,
  type RunStatus,
  seriesColorOf,
  type StepStatus,
  type ToolCall,
} from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LoaderIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { ClockGate, LiveDuration } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { AGENT, type Tool, type ToolId, TOOLS } from './data';
import { SESSION } from './run-script';

const AGENT_COLOR = seriesColorOf(1);

const STEP_WORD: Record<StepStatus, string> = {
  upcoming: 'Upcoming',
  running: 'Running',
  done: 'Done',
  failed: 'Failed',
  skipped: 'Skipped',
};

const RUN_WORD: Record<RunStatus, string> = {
  idle: 'Queued',
  running: 'Running',
  waiting: 'Waiting',
  done: 'Done',
  failed: 'Failed',
  cancelled: 'Stopped',
};

const DONE_MESSAGE =
  'Run finished: the release notes are drafted and a pull request is open.';

function isToolId(value: string): value is ToolId {
  return Object.hasOwn(TOOLS, value);
}

function toolOf(call: ToolCall): Tool | null {
  if (!isToolId(call.tool)) {
    return null;
  }
  return TOOLS[call.tool];
}

function resultOf(call: ToolCall) {
  if (typeof call.output === 'string') {
    return call.output;
  }
  return '';
}

function announcementOf(run: RunSnapshot) {
  if (run.status === 'done') {
    return DONE_MESSAGE;
  }
  return '';
}

function StepGlyph({ status }: { status: StepStatus }) {
  if (status === 'done') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  if (status === 'running') {
    return <LoaderIcon className='text-muted-foreground size-4 animate-spin' />;
  }
  return (
    <span className='hairline-ring ring-foreground/25 size-3.5 rounded-full' />
  );
}

function PlanRow({ step }: { step: PlanStep }) {
  const isUpcoming = step.status === 'upcoming';

  return (
    <li className='flex h-7 items-center gap-2.5 text-[13px]'>
      <span className='flex size-[18px] shrink-0 items-center justify-center'>
        <Swap swapKey={step.status}>
          <StepGlyph status={step.status} />
        </Swap>
      </span>
      <span
        className={cn(
          'min-w-0 flex-1 truncate transition-colors duration-200',
          isUpcoming && 'text-muted-foreground'
        )}
      >
        <span className='sr-only'>{STEP_WORD[step.status]}: </span>
        {step.title}
      </span>
    </li>
  );
}

/** What a call found unfolds under it once it is done; its time sits in a box of its own width. */
function CallRow({ call }: { call: ToolCall }) {
  const tool = toolOf(call);
  const isRunning = call.status === 'running';
  const isDone = call.status === 'done';
  const result = resultOf(call);

  return (
    <div className='flex items-start gap-2.5 pb-2'>
      {tool && <BrandTile brand={tool.brand} size='lg' title={tool.name} />}
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='py-1 text-[13px] leading-5 text-pretty'>{call.label}</p>
        <Fold open={isDone}>
          <p className='text-muted-foreground text-xs text-pretty'>{result}</p>
        </Fold>
      </div>
      <span className='flex h-7 shrink-0 items-center gap-2'>
        <LiveDuration
          item={call}
          isRunning={isRunning}
          className='text-muted-foreground w-11 text-end text-xs'
        />
        <CallStatusMark status={call.status} />
      </span>
    </div>
  );
}

/**
 * A small run of the agent, playing beside the hero: the plan ticks while two tools are called
 * and their results unfold, under the ink of a run in progress. Clicking in it lets the run end;
 * Replay starts it again.
 */
export function LiveRun() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state: run,
    isFinished,
    restart,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const isRunning = run.status === 'running';
  const runWord = RUN_WORD[run.status];
  const canReplay = isFinished && !isAutoplaying;
  const announcement = announcementOf(run);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-h-[21rem] w-full flex-col rounded-2xl p-1.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
      >
        <div
          role='group'
          aria-label={`Run of ${AGENT.name}: ${run.title}`}
          className='bg-foreground/[0.03] relative isolate flex flex-1 flex-col gap-3 rounded-[calc(var(--radius-2xl)-0.375rem)] p-4'
        >
          <Wash color='var(--info)' isShown={isRunning} />
          <div className='flex items-center gap-2.5'>
            <MeshTile seed={AGENT.name} color={AGENT_COLOR} size='lg' />
            <div className='flex min-w-0 flex-1 flex-col'>
              <p className='truncate text-[13px] font-medium'>{AGENT.name}</p>
              <p className='text-muted-foreground truncate text-xs'>
                {run.title}
              </p>
            </div>
            <div className='flex shrink-0 flex-col items-end text-xs'>
              <Swap swapKey={runWord} className='font-medium'>
                {runWord}
              </Swap>
              <LiveDuration
                item={run}
                isRunning={isRunning}
                className='text-muted-foreground w-12 text-end'
              />
            </div>
          </div>
          <ol aria-label='Plan' className='flex flex-col'>
            {run.plan.map((step) => (
              <PlanRow key={step.id} step={step} />
            ))}
          </ol>
          <ul aria-label='Tool calls' className='flex flex-col'>
            <AnimatePresence initial={false}>
              {run.calls.map((call) => (
                <motion.li
                  key={call.id}
                  {...presence}
                  className='overflow-hidden'
                >
                  <CallRow call={call} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
        </div>
        <div className='flex min-h-9 items-center justify-between gap-2 ps-2.5 pe-1'>
          <span className='text-muted-foreground text-xs'>
            Illustrative run
          </span>
          <ReplayButton isShown={canReplay} onReplay={restart} />
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

import type { SessionConfig } from '@/registry/ndeko/hooks/use-session';
import {
  emptyRun,
  type PlanStep,
  type RunAgent,
  type RunSnapshot,
} from '@/registry/ndeko/lib/agent-run';
import {
  applyBatchAt,
  batch,
  reduceBatch,
  restingOf,
  type RunBatch,
  type RunStep,
} from '@/registry/ndeko/lib/run-session';

import { AGENT, RUN_TITLE } from './data';

/** Added idle and set running by the first batch, so the run stamps its start. */
const WRITER: RunAgent = {
  id: AGENT.id,
  name: AGENT.name,
  series: 1,
  status: 'idle',
};

const PLAN: PlanStep[] = [
  {
    id: 'read',
    title: 'Read the pull requests merged since 4.1',
    status: 'upcoming',
  },
  { id: 'group', title: 'Group the changes by area', status: 'upcoming' },
  {
    id: 'draft',
    title: 'Draft the notes and open a pull request',
    status: 'upcoming',
  },
];

export const INITIAL: RunSnapshot = emptyRun({
  id: 'release-notes',
  title: RUN_TITLE,
  agents: [WRITER],
  plan: PLAN,
});

/** A plan of three steps that tick in turn, with one call to GitHub and one to Linear on the way. */
const SCRIPT: RunStep[] = [
  batch(
    700,
    { type: 'run.started' },
    { type: 'agent.updated', id: AGENT.id, patch: { status: 'running' } },
    { type: 'step.updated', id: 'read', patch: { status: 'running' } }
  ),
  batch(600, {
    type: 'call.started',
    call: {
      id: 'merged',
      tool: 'github',
      label: 'List the pull requests merged since 4.1',
      status: 'running',
      agentId: AGENT.id,
    },
  }),
  batch(
    1700,
    {
      type: 'call.updated',
      id: 'merged',
      patch: { status: 'done', output: '38 pull requests across 6 areas' },
    },
    { type: 'step.updated', id: 'read', patch: { status: 'done' } },
    { type: 'step.updated', id: 'group', patch: { status: 'running' } }
  ),
  batch(700, {
    type: 'call.started',
    call: {
      id: 'issues',
      tool: 'linear',
      label: 'Match them to the issues they close',
      status: 'running',
      agentId: AGENT.id,
    },
  }),
  batch(
    1600,
    {
      type: 'call.updated',
      id: 'issues',
      patch: { status: 'done', output: '31 issues closed, 4 still open' },
    },
    { type: 'step.updated', id: 'group', patch: { status: 'done' } },
    { type: 'step.updated', id: 'draft', patch: { status: 'running' } }
  ),
  batch(
    1800,
    { type: 'step.updated', id: 'draft', patch: { status: 'done' } },
    { type: 'agent.updated', id: AGENT.id, patch: { status: 'done' } },
    { type: 'run.finished', status: 'done' }
  ),
];

/** Under reduced motion the run rests finished, with both results to read. */
const RESTING = restingOf(INITIAL, SCRIPT, applyBatchAt);

const LOOP_AFTER_MS = 3800;

export const SESSION: SessionConfig<RunSnapshot, RunBatch> = {
  reducer: reduceBatch,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

import { CopyButton } from '@/registry/ndeko/ui/copy-button';

type InstallChipProps = {
  command: string;
};

/** The command that installs the product, on one line, with a button that copies it. */
export function InstallChip({ command }: InstallChipProps) {
  return (
    <div className='bg-foreground/[0.04] inline-flex h-9 max-w-full items-center gap-2 rounded-full ps-3.5 pe-1.5 font-mono text-[13px]'>
      <span aria-hidden='true' className='text-muted-foreground select-none'>
        $
      </span>
      <code className='min-w-0 truncate'>{command}</code>
      <CopyButton
        text={command}
        label='Copy the install command'
        className='rounded-full'
      />
    </div>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type ToolId = 'github' | 'linear';

export type Tool = {
  id: ToolId;
  name: string;
  brand: BrandSlug;
};

export const HERO = {
  announcement: {
    label: '4.2',
    text: 'Every run now replays step by step',
    href: '#',
  },
  titleStart: 'Let an agent write your',
  /** The last word of the title turns over; the run beside it writes the first one. */
  titleWords: ['release notes', 'changelogs', 'migration guides', 'test plans'],
  titleSpoken: 'release notes, changelogs, migration guides and test plans',
  description:
    'Quillrun reads your repository and your tracker, plans the work and opens a pull request for you to review. Nothing merges without you.',
  primaryAction: 'Start building',
  secondaryAction: 'Read the docs',
  command: 'npx quillrun init',
};

export const AGENT = {
  id: 'writer',
  name: 'Writer',
};

export const TOOLS: Record<ToolId, Tool> = {
  github: { id: 'github', name: 'GitHub', brand: 'github' },
  linear: { id: 'linear', name: 'Linear', brand: 'linear' },
};

export const RUN_TITLE = 'Release notes for 4.2';
